    (7, 19, "ክ፱. ፳B ፡ R= የስውን ደም ያፌስስ ስለ አፈስሰው ስለዚያ ደም ፈንታ ደሙ ይፈሳል ፡ ሰውን በአግዚአብሔር አምሳል ፈጥሬ R ዋለሁና።"),
    (7, 20, "አናንተ ግን ብዙ ተበዙ ምድርንም ምሏት = አግዚአብሔርም ኖግን ተዳገረው ፣ iy ከኣርቡ ጋር አንዲህ ብሎ።"),
