    (7, 23, ") ከናንተ ጋራ ኪዳኔን አፀናለሁ ፡ አንግዲህ ወዲህ ሥጋ የሰበብ ሁሉ በጥፉት አይሞትም ፡ ምድርም ሁሉ ለማጥፋት - እንግዲህ ወዲህ የጥፋት ውኃን አላመጣም።"),
