    (9, 11, "i ጌቴር ጌሴምንን ! ኬዌዎንን ፡ ፌርዜዎንኝን ፡ ሴንን « ሔራጮዴዎንኘ፡ ስማንሔርን፡ ጸጣማቲን ወለደ (ጸሥራ ጸንድ ይሆናሉ)።"),
    (9, 12, "| ከዚህ በኋላ የክኝነጸን ወገዋች ተጀ።"),
    (9, 13, "ና የክነጸን ጸገራቸው ከሲዶን ጀምሮ አስክ ጋዛና. አስክ ጌቕ ራፉ ድረስ ሆነ፡ አስክ ገሞራና እስክ ስዶም።"),
    (9, 14, "እስክ ፈና ዮን አስክ ዳማ ፡ አስክ ሌላ ድሪስ ይደርሳል።"),
