    (9, 20, "ክርስቲያን ሃይማኝ ትና መሥርት ፅራፍ ፲።"),
    (9, 21, "Ey ሐድራን አዚላን ፣ ዴቁላን።"),
    (9, 22, "ኡበብልን ፣ አቤሜሌክን ፡ ጴጌሆንን።"),
    (9, 23, "| ሑፎርን ፡ ዊን, ሊጺዮስርን እነዚህ ሁሉ የሦቃጢን ልጆት ናቸው።"),
    (
        9,
        24,
        'AER tir") nr tu #) ያሆ 2 ምሥራቅ ተራራ ድሪስ ነወ የሴም ልጆች በየነገዳቸውና በየቋንቋቸው በየምድራ ቸውና ፡ በየሕዝበቸው ፡ አነዚህ ናቸው = የኖሣ ልጆቹ ነገዶች አንደ ትውልዳቸው በየሕዝበቸው እነዚህ ናቸው ፡ ከእነዚህም ተወልደው አሕዛብ ከጥፉት በኋላ በምድር ላይ ተበተኑ = ኣር ሓጋ።',
    ),
    (9, 25, "ድእ ኣ.ኣ re po yey።"),
    (9, 26, "የሰው ሁሉ ቋንቋው ' አነጋገሩም አንድ ነበር።"),
    (9, 27, "-. ከምሥራቅም በተነው ጊዜ አንዲህ ሽነ፡ በሰናኦር ምድ ር-በፊ ሜዳ አገኙ፡ በዚያም ሰፈሩ።"),
    (9, 28, "ክንዱ ክንዱ ጋር ኑ፡ ጡብ እንሥራ በእለት ተ በን እናብስለው ተባባሉ ፡ ጡውበቐው ደንጊያ ሆነላቸው « ጭቃ ቸውም ሙጫ ነበር።"),
    (
        9,
        29,
        "ዘፍ. ፲፪ ፡ {= ሣ8 Bs እርስ በርሳቸው አንዲህ ተባበሉ ፡ ኑ ፣ መንደር እንቁር ምር ጫፉ እስከ ሰማይ የሚደርስ ግንብም እንሥራ ፡ በም ድር ሁሉ ከመበተናችን በፊት ፡ ለአኛ የስማችን መጠሪያ እናድርግ።",
    ),
    (10, 1, 'ኣግዚአጾብሔርም ሰዎች የሠሩትን ያንን ግንብ ያይ ዘንድ" ወደ መንደራቸው ወረደ።'),
    (
        10,
        2,
        "እግዚኣብሔርም እንዲህ አለ ሁሉም አንድ ቤተ ሰብ፡\" ጸንድ ቋንቋ ናቸው ፡ እንደዚህ ያለ ሥራም ሊሠሩ ጀመሩ፤ ጸሁንም በልባቸው ያሰቡትን መሥራታቸውን አይተጢዉም፣ ኑ'. እንውረድ ቋንቋቸውን እንለያየው ፡ ጸንዱ ክንዱ ጋር የሚናገሩትን አንዳይሰማሙ = ዛፍ. 8 ፡ ፪2።",
    ),
    (10, 3, "እግዚአብሔርም ቋንቋቸውን ለያየ ፡ በምድርም ሁሉ በተናቸው ፣ ከዚህ በኋላ ያቸን መንደር መቈርቂር ፡ ያን ንም ግንብ መሥራትን ተዉ።"),
    (
        10,
        4,
        "ስለዚህም ስሟ ባቢሎን ተባለ ፡ እግዚአብሔር በዚያ የሀገሩን ሁሉ ቋንቋ ለያይቷልና ፡ ከዚያም እግዚአብሔር ሰዎችን በምድር ሁሉ በትኗቸዋልና = የሴምም ልደቱ እንዲህ ነው ከጥፋት በኋላ በሁለተኛው ዓመት አርፋክስድን ሊወልድ ለእርሱ ከተወለደ ሾ ዓመት ሁኖችት ነበር።",
    ),
    (
        10,
        5,
        "ዘፍ. ፲ ፡ ፳፪ - ፳፪ = ምም አርፋክስድን ከወለደው በኋላ ደየ ዓመት ኖረ፡ ወንዶችንና ሴቶችንም ልጆች ወለደ , ሞተ = አርፋክስድም ሾሸዩ ዓመት ኖረ፡ ቃይንምን ወለደ።",
    ),
    (
        10,
        6,
        "Ny -ጸርፋክስፎ ቃይንምን ከወለዴው በኋላ 8፩፻ኝ ዓመት ኖረ! ሴቶች ልጆችንና ወንዶች ልጆችንም ወለደ ሞተ፡ ያይንምም ዩዘ ዓመት ኖረ ሳላንም ወለደ፡ ቃይንም ሳላን ከወደው በኋላ 8፻ሸ ዓመት ኖረ፡ ሴቶች ልጆችንና ወንድች ልጆችንም ወለደ ፡ ሞተ።",
    ),
    (
        10,
        7,
        ".. ሳላም ዩ፳ ዓመት ኖረ ኤበርንም ወለደ = ክርስቲያን ሃይማነ ፐኝ ዳ ሥርዓት ፍ ፲፪ • ሰላም ኤስርን ከወለደው ቦኋላ 8፻ቋ ዓመት ኖረ! ሴቶች ልጆችንና ወንዶች ልጆችንም ወለደ ! ሞተ።",
    ),
    (10, 8, "ኤዕርም ጀብ፱ ዓመት ናረ ፋሌቅንም ወለይው . ኤክርም ፋሕቅን ከ ወለይ በኋላ ፩፻ቋ ዓመት ኖረ ፡ ሴቶ x ልጆችንና ወንዶች ልጆችንም ወለደ ፡ ሞተ።"),
    (
        10,
        9,
        "ፋሴቅም ዩ፱ ዓመት ኖሪ ፡ ራግውንም ወለደ =. ፋሌቅም ራግውን ከወለደው በኋላ ፪ዩ፱ ዓመት ኖሪ ሴቶች ልጆችንና ወንዶች ልጀጆጀትንም ወለደ ፡ ሞተ = ራግውም የፀ ዓመት ኖሪ ፡ ሌሮሣግንም ወለደ።",
    ),
    (10, 10, "ራግውም ሴሮሣንም ከወለደ በሓላ ዩ፻፮ ዓመት ኖረ ቤቶች ልጆችንና ወንዶች ልጆችንም ወለደ! ሞተ።"),
    (10, 11, "ሌሮግም ፲፬ ዓመት ኖረ ፣ ናክርንም ወለደ።"),
    (10, 12, "ሴሮግም ናከርን ከወለደው በኋላ ፪፻ ዘመን ኖረ ፡ ሌቶች ልጆችንና ወንድች ልጆችንም ወለደ ፡ ሞተ።"),
    (10, 13, "ናኮርም ዩ፱ ዓመት ኖረ! ታራንም ወለደ።"),
    (10, 14, "ናኸርም ታራን ከወለደ በኋላ የጃ ዓመት ኖሪ ፡ ሴቶች ልጆችንና ወንዶች ልጆችንም ወለደ ፡ ሞተ።"),
    (10, 15, "ታራም ሾ ዓመት ኖረ፣ አብራምን ፣ ናክርን ፡ አራንንም ወለይ።"),
    (10, 16, "፣ f አራንም ሎጥን ወለደ።"),
    (10, 17, "አራንም ከአባቱ በፊት በተወለደበት አዚንር በክላውይ . ዎን ምድር ሞተ።"),
    (
        10,
        18,
        "ናክኮርና አብራምም ሚስቶች ጸገቡ ፡ የአብራም ሜስት ቦራ ትበል ነበር፡ የናክር ሚስትም ሜልክ በል ነበር ፡ . ሜልከም የሜልክና የስክ አበት የ አራን ልጅ ናት =. ስራ ግን መክን ነበረች ልጅም አልነበራትም ፡ ታራም ልጁን ጸብራምን የአብራምን የወንድም ልጅ ሎጥንም ፡ የልጂን የአብራምን ሚስት ምራቱ ጸራን ወስዳቸው።",
    ),
    (10, 19, ". = ወዴ ከነአን መድርም ይቕዱ ዘንድ ከከላውዴዎን አወ ጣቸው ፣ ወደ ክራንም በደሪሱ ጊዜ በዚያ አደሩ።"),
    (10, 20, "ታራም በሕይወት የኖረበት ዘመኑ ሁሉ ዩጀጀሯ ዓመት ሆነ፡ ታራም በከራን ሞተ።"),
    (10, 21, "አግዚአብሔርም አብራምን ካገርህ ወጥተህ ከዘመድህ ካበትህም ወገን ተለይተህ ፡ አኔ ወደማዛይህ ምድር ሂድ a ጸሰው፣ ምፅ. ፲ጀ፣31፣ ግብ. ሓዋ. ፮!፲።"),
    (
        10,
        22,
        "ታላቅ ሕዝብ አዶርግኻለሁ፣ ስምህም ከፍ ከክፍ አደርን ዋለሁ ፣ የተበረኽከሀም ትሆናለህ = የሚያክከብሩህንም አከብራቸዋለሁ ፡ የሚረግሙህንም እረ ግማቸዊዋለሁ ፡ የዚህ ዓለም አሕዛብም ሁሉ ባንተ ድይክብ ራሉ አክለው።",
    ),
    (10, 23, "ዘጐ. ፳ቛ8 ፡B።"),
    (10, 24, "አብራምም እግዚአብሔር አንዳዘዛው ሄደ! ሎጥም ከቡ ጋራ ደ አብራምም ክከክራን በወጣ ጊዜ ፅድሜው &E ነበር።"),
    (10, 25, "ክብራምም ሚስቱ ዕራን ወሰደ ፡ የወንድሙን ልጅ ሎጥ ንም በክራን ያጠራቀሙትን ገንዘባቸውንም ሁሎ ይዞ ወይ ከነአንም ምድር ደሪሱ።"),
    (10, 26, "ዘፍ. ፲8 ፡ ጸክ።"),
    (10, 27, "፲8፡ ፲፩ = ክርስቲያን ሃይማዛ ትኛ ሥርዓት ፍ ፲፪።"),
    (10, 28, "i [1s አብራምም ችን ሀንገር ረም ፅገጨት አስከ አለበት ኣስክ ሴኬም ድረስ ዘራት ፡ የክነአን ሰዎች ግን የዚያን ጊዜ በዚያች አገር ነበሩ።"),
    (10, 29, "ዕብ ፲፩, 9: አግጻአብሔርም ለአብራም ታየው ፡ ይችንም አገር ለል ጆችህ እሰጣታለሁ አለው ' አብራምም በዚያ ለተገለጠለት ለእግዚአብሔር መሥዋዕት አዘጋጅ።"),
    (
        10,
        30,
        "ዘፍ. ፲ር ፡ ፲ጀ =, ከሄያም ወደ ምሥራቅ ወዬ ቤቴል ምድር ሄደ ፡ በቤቴ ልም በጋይ ስኩል በስተምዕራብ ድንኳኑን ተክል ፡ በዚ ያም ተቀመጠ ፡ በዚያም ለአግዚአብሔር መሠዊያ ሠመራ የእግሄአብሔርንም ስም ጠራ።",
    ),
