    (17, 5, ") አብርሃምም እሁን ልናገር ፍቀድልኝ በዚያ 1 ቤገኙስ፣፤ አስው ፡ ከለ ፲ሩም አላጠፉም አለው።"),
    (17, 6, "አግዚአብሔርም ጸብርሃምን ማነጋገሩን ከፈጸመ በኋላ ተሠወረው ፣ ጾብርሃም ወደ በቦታው ያመለ።"),
    (17, 7, "እነዚያ ፪ቱ መልእክተኞችም ማቻ ጊዜ ወደ ሰዶም ደረሱ ፡ ሎጥም በሰዶም አገር በር ተቀምጦ ነበር ፡ ቧያቹ ውም ጊዜ ተነሥቶ ተቁበላቸው ፡ በገይደላቸው።"),
    (
        17,
        8,
        "ዘፍ. I ¢ Rs IR gs ፲ቶቹ ! ወደ ባርያችሁ ቤት ገብታችሁ እዪሩ አማራች ( ሁንም ቃቻጠቡ ፡ በጧትም’ ማልዳችሁ ጐዳናችሁን ሄዱ አላቸው ፡ አይሆንም በአደበበይ ክናድራለን አንጂ አሉት።",
    ),
    (17, 9, "ዘፍ. ኝ፫ ፡ ጽ፱።"),
    (17, 10, "ሉቃ. ፳፱፡ ጽሯጀ።"),
    (17, 11, "ግድ ግቡልኝ አላቸው ፡ ክሱ ዘንድም ወዴ ቤቱ ገቡ፡ ቁጣ ድፎም አዛጋጀላቸው አነሱም በሉ።"),
    (17, 12, "ከመተኛት በፊትም የዚያች አገር ሰዎች ቤታቸውን ከበቡት ሰዎቻቸው ሁሎ ታላቁም ታናሹም በአንድነት።"),
    (17, 13, "ሎጥም ወርተው እነዚያ ማታ ወደ ኣንተ የገቡ ሰዎች የት አሉ፤፣ ወደኛ ጸውጣቸውና እንወቃቸው አሉት።"),
    (17, 14, "ሎጥም ወደ እነርሱ ወደ ደጅ ፊት ለፊት ወማ በቦሩ ንም በስተሓላው ዛጋ።"),
    (
        17,
        15,
        'ወንድሞቹ ! አይገበም በአነዚክ ሰዎች ላይ ክፉ ነገር አታድርጉ = እነሆ በል ያላገቡ ፪ት ቋቶት "ልጆች አሉኝ ኣውጣ ሓችሁና አንደወደዳችሁ አድርጓቸው ፡ ነገር ግን ወደ ቤቴ | በገቡ በእነዚሀ ሰዎች ላይ ምንም ምን ክፉ ሃገር ጸታድ ርጉ አላቸው።',
    ),
    (17, 16, "ወዲያ ሂድ ከአኛ ጋር ልትኖር መጣሀ እንጂ ልትገዛን አይዴለም |! አሁንም ከእነሱ ይበልጥ አንተን እናሠቃ ራፍ ፲ክ።"),
    (17, 17, "= | HE ክርስቲያን ሃይማኝ ትኛ ሥርንች Fy. ይሃለን አሉት ፡ እጅግ በረቱበት በሩንም ሊሰብሩት ቀረቡ።"),
    (17, 18, "' እነዚያም ሰዎች አጃቸውን አውጥተው ሎጥን ጐት ተው ወደ አነሱ ወደ ቤት ውስጥ እገቡት ፡ ደጃፉንም ዘጕ።"),
    (17, 19, "በዚያ ቤት በር ፊት ለፊት ያሉትን ሰዎች ግን ዓድና ቸውን ኣሣወሯቸው ፣ ትንሹንም ትልቁንም በሩን በመፈ ለግ ደከሙ አላገኙትም።"),
    (
        17,
        20,
        "እተዚያ መልእክተኞችም ሎጥን አንዲህ አሉት ፡ በዚህ ያለሀ ዘመድ ፡ አማች ፡ ይኖርህ ይሆን ፣ ወንዶች ልጆች ሴቶች ልጆች እንዳሉ ፡ የምትወዶደው ወዳጅም በዚች አገር አንዳለ ከዚች ቦታ አውጣቸው።",
    ),
    (17, 21, ". አኛ ይሀቹን ቦታ አናጠፋተታለንና ጩኸታቸው’ በአግዚ አብሔር ከፍ ከፍ ብሏልና ልናጠፋት ልዞናል።"),
    (
        17,
        22,
        "ሎጥም ወጥቶ ሁለቱን ሴቶች ልጆቹን የሚያገቡት አማ ቖቹን ተነው ከዚች አገር ውጡ ፡ አግዚአብሔር ድህ ቺን አገር ያጠፋታልና አላቸው ፡ ለጸማቾቹ ግን በቀልድ የሚነግራቸው ይመስላቸው 'ነበር.።",
    ),
    (
        17,
        23,
        "ኤር. 38 ' 5 ራኣ. ፲ቻ፳፡ ፩= ጎሕም በቀደደ ጊዜ መልእክተኞች ሎጥን ተነሥ ሁለ ቁ ልጆችህንና ሚስትህን ይዝህ ውጣ፡ አንተም በዚህች ሀገር ሰዎች ኃጢጸት እንዳትጠፉ አያሉ ያስቸዙሉችት Rመርs HE, Br ifs በዘገየ ጊዜም አነዚያ ሰዎች አሱንና ሚስቱን ሁለቱን ልጆቹንም አጅ አጃቸውን ይዘው አወጧቸው ፡ አግዚ አብሔር ራርቶላቸዋልና።",
    ),
    (17, 24, "ወደ ውጭም በወጡች ጊዜ ነፍስህን ጾድን ወደ ጃላ ሀም አትይ ' አንተንም መከራ እንዳታገኝጓህ በዳርቻዋ በዚ ያችም አገር ተራፉ አትቁም 'አሉት።"),
    (17, 25, "ዛፍ ፲፱፡ ፩፮ = ሎዋም እንዲህ አላቸው ፡ ጌቶቹ ! በጄ በሉኝ።"),
    (
        17,
        26,
        "= በፊትህ ምሕረትን አግኝቼ ኣንዶሆኝ ሰውነቴንም ታድ ናት ዘንድ ፡ ቸርነትህን አብዝተሀልኝ አንደሆነም. መከራ ጸግጃቶኝ አንዳልጠፋ እኔ ወደ ተራራ TE ራሴን ማዳን አልችልም።",
    ),
    (
        17,
        27,
        "አነሆ ይህች አገር ቅርብ ናት ትንሽ ናት ፡ ወደዚያች ፍጩ ራሌን ላድን ፡ ግን ዘውነቹ ከዳነች ችንሽ አይደ ለችም =. | | እንዲህ አለው እናሆ ፊትህን ክአልመለስኩትም (ልመና ህን ተቀብያለሁ) ስላ እሷ የነገርሽኝን ይቺን አገርም ዶላ ስፋትም።",
    ),
    (18, 1, "ኢዮ. Ly B= እንግዲህ አፍጥን ወደዚያም ደርሰህ ራስህን አድን ወደዚያም እስክትደርስ ምንም ምን አላደርግም ና ' ስለዚ ህም ያቺ አገር ሴጎር ተበለች።"),
    (18, 2, "ፀሐይ በምድር ላይ ወጣ ! ሎጥም ወዴ ሴንር ገበ = እግዚ አብሔርም ከሱ ዘንድ ከሰማይ በገሞራና በሰዶም እሳትና ዲን አዛነመ።"),
    (18, 3, "ሕዝ ፲ሄ፡ HB -፮።"),
    (18, 4, "= አሞ. 8፡1፲8= እነዚያን አገሮች አውራጃቸውንም ከሚኖሩባቸው ዕዎ | ችሁሉ ጋራ አጠፋቸው ! የም ድራቸው ንም አዝመራ ሁሉ።"),
    (18, 5, "ጃርክስኙያ፣ F) ኝሣይማኛችናኛ ሥርኖች ራፍ ፲ = የሎጥ ሚስትም ወደ ሓእላዋ ተመልጳፅ አይታ የጨው ዪንጊያ ሆነች።"),
    (18, 6, "አብርሃምም በአግዚአብሔር ፊት ወዬ ቋመበች ወዴ ዘየ ቦታ ኘሥግም $ደ።"),
    (18, 7, "ወደ ገሞራና ወደ ሰዶም አየ አውራጃዊንም ሁሉ በየም ጊዜ አነሆ እንደ ምዴጃ ጢስ ከምድርም ኣት ሊወጣ እየ።"),
    (18, 8, "አግዚጾብሔርም ሎጥ የሚኖርበቸውን ኣነዚያየን ይገሮ ችና አውራጃቸውንም ሁሉ በኦአጠፉ ጊዜ አንዲህ ሆነ፡ ኢግከ አብሔር አብርሃምን ኣስበው ፡ ሎጥም ከጥፋት ጽዳ ነው።"),
    (18, 9, "ሎጥ ከሌጎር ወጥቶ በተራራ ተቀመጠ ' ሁለቱም ሴቶች ልጆች አብረዉት ነበር፡ በሴጎር መቀመጥን ፊርቷልና በዋሻ ውስጥም ተቀመጠ ፡ አሱም ሁዘት ሴቶች ልጆቹም።"),
    (18, 10, "ክፍ. 38 IE -IB= ታላፍቱ ታናሺቱን አንዲህ አለቻት ፡ አንሆ አበታችን አርጅቷል ፡ በምድር ሁሉ እንደሚበቫው ስማድረግ ወደ ኣኛ የሚገበ ጳው የለም።"),
    (
        18,
        11,
        "ነዬ ወይን አናጠጣውና ከክቡ ጋር አንተኛ፡ ከአባታች ንም ዘር ኣናስቀር = ለኦአበታቸውም ወይን አጠጡት ፡ በዚያችም ቤሊት PN ቂቱ ገብታ ክበቷ ጋር ተኛች አሱ ግን ከትተኛም ስትነ ሣም አላወቀም = ከዚህም በኋላ ታላቂቱ ታኝቪቱን እንዲህ አለቻት ፡ አንሆ ቸናንትና አኔ ከአባታችን ጋራ ተኛሁ ፡ ዳግመኛም ወይን እናጠጣው አንቺም በዚች ሌሊት -ከአሱ ጋራ ተኝ፡ ከአበታችንም ዘር አናስቀር።",
    ),
    (18, 12, "በዚያችም ሌሊት ወይን አጠጡት ! ታናቪቱ ግብታ ክአ በቷ ጋራ ተኛች፡ አቡ ግን ስትተኛም ስትነሣም ጽላወቀም።"),
    (18, 13, "የሎዊ ሁለቱ ልጆቹም ከአበታቸው ፀነሱ።"),
    (18, 14, "= ታላቂቱም ወንድ ልጅ ወለደች ስሙንም ሞክብ አለ ችው ፡ ይኸውም ከአባቱ የወለድኩት ማለት ነው አሱም እስከ ዛሬ የሞአክባውያን አስት ሃው = ህዳ. ፪፡ B።"),
    (18, 15, "ታናቪቱም ወንድ ልጅ ወለደች ፣ ስሙንም አሞን አለ ችው ፡ ከወገኔ ወለድኩት ስትል ፡ አሱም አስከ ጃሬ የአሞ n ናውያን አበት ነው = ዛዳ. ፪፡ ፲፱።"),
    (18, 16, "= ምፅራፍ 20: አብርሃምም ከዚያ ተነሥቶ ወደ አዚብ ምድር ሄደ፡ በሱሬና በቃዴስ መክከል ኖረ፡ በጌራራም ተቀመጠ።"),
    (18, 17, "uፍ. IZ 8- RFs I2፡ 1-18 REifF።"),
    (18, 18, "is iB አብርሃም ሳራ ሚስቱን እግ ናት አላቸው ፥ የጌራራ ንጉሥ አቤሜሌክም ልከ ሳራን ወሰዳት።"),
    (
        18,
        19,
        "፳፮, 2-18 = በዚያች ሌሊት አቤሜሌክ ተኝቶ ሳለ አግዚአብሔር ወደ አቤሜሌክ ግበ በሕልም እቢ የጉልማሰ ሚከት ናትና ከስዚች ስስ ወሰድክት ሌት አንተ አነሆ ቸሞታለህ . አለው።",
    ),
    (18, 20, "መዃ. ዩጀ፡ ፲8።"),
    (18, 21, "ክርስቲያን ሃይማኖትና ሥርዓት ራፍ ፳ | [i] ኣቤሜሌክ ግን ጸልነክትም ነበር ፡ አቤሜይክም አንዲህ አለ በኣውነት ያላወቀ ሰውን ቻመጠፋለህን፣ ዛፍ. ፲፭ ! ፳፻።"),
    (18, 22, "ኣሱ እግቴ ናት አለኝ ፡ አሷም እሣቱ ነኝ አለችኝ ፡ ይክ ንንም ሥራ በንጹሕ ልቤ በንጽሕ ኣጁ አደረግሁት አለ ው።"),
    (
        18,
        23,
        "አግዚአብሔርም በሕልም ክንዲህ አለው ፡ እኔም በዋ ሀነት፱ አንዳይረግኸው አውቐዊአለሁና ራራሁልሀ ኃጢጸ ‘ትም እንዳትሠራ መበቅሁህ፡ ስለዚዕፀም እንድትቀርበት አልፈቀድኩልህም።",
    ),
    (18, 24, "ዘፍ. 8B ፡ B።"),
    (
        18,
        25,
        "መዝ. 48፡8, አሁንም ለዚያ ሰው ሚስቱን መልስጻት ፡ ደግ ሰው ነውና ስለ ጸንተም ይጸልይልሃል አንተም ትድናለህ ፡ በትመልስለት ግኝ አንተ ሞትን አንድዥ'ሞችት ፣ ንተ የሆ . ነውም ሁሉ አንዲጠፋ ወቅ ጸለው።",
    ),
    (
        18,
        26,
        "ኢዩ. ጓ፪፡፣ = አቤጫሟሴክም በጧኝ ተነሥቶ ጸኸኽክከፎቹን „ጠራቸው ይህንንም ነኝር ነገራቸው ፡ ቤቱ ሰዐቹም ሁሉ wis እግዚአብሔርን ፈሩት = oe አቤሜሌክም አብርሃምን ጠርቶ ይህ በክኔና -በመንሣ ' ሥቴ ላይ ያደረግኸው “ምንድር ነው'፥ ማንም የማይሠሙ ራው ታላቅ ኃጢጸት ነው አለው።",
    ),
    (18, 27, "አቤሜሟሴክም አብርሃምን ይህን ያደረግኸው ምን ጸይ ተሀ ነው፣ አለው።"),
    (18, 28, "አብርሃምም እንዲህ አለ ምናልበት በዚህ በቻ አግዚ አብርሔርን መፍራት . የለምና ኻስ ሚስ SRN ብዬ ሃው።"),
    (18, 29, "ምባ. ፲፮ 6: ዳግመኛም በአውነቱ አሣቴ የአባቴ ወገን ናት ፡ ከአናቱ በኩል አይደለችም ፡ ሚስትም ሆነችኝ »።"),
    (18, 30, "ዛፍ. ፲8 ፡ ፳B = እግዚአብሔርም ክባቴ ቤት ባወጣኝ ጊዜ ይህንን በጎ ሥራ አድርጊልኝ ፣ በገበን በትም ቦታ ሁሉ ወንድሜ ነው በዪ አልኋች።"),
    (18, 31, "ጾቤሜሌክም ቪሕ ምዝምዝ ብርን ፡ ሴቶች አገልጋዮ ችንና ወንዶች አገልጋዮችን ላሞችንና በጎችንም አም ጥቶ ለአብርሃም ስጠው ፡ ሚስቱ ሳራንም መለሰለት።"),
    (18, 32, "ዛፍ. 18 12 oY አቤሜሌክም አብርሃምን እነሆ አገሬ በፊትህ ናት በወ ደድከው ኑር አለው።"),
    (18, 33, "Vy ስራንም እነሆ ለወንድምሽ ሺሕ ምዝምዝ ብር ሰጠ ሁት ፡ ይሀም ለፊሻሽ ጌጥ ይሁንሽ አላት ፡ በሁሉም በጎ ነገር ተናገራት።"),
    (19, 1, "ዘፍ. ፳ጀ ፡፣ ፳፪ - ፲፪ = አብርሃምም ወደ እግዚአብሔር ለመነ እግዚአብሔርም አቤሚሟሌሔክን ፈወሰው ፥ ሚስቱንም በሮቹንና ልጆቹን ቤተ ሰቦቹንም ልጆቹንም ወለዱ።"),
