    (19, 5, "ዕብ TR! hs TA. Bs Rs 4 አብርሃምም ላራ የወለደችለትን ያንን ቋፃን ይክሐፍ ብሎ ጠራው ፥ ዘፍ. ፲፮ ፣ ፲፱።"),
