        24,
        1,
        "| እኛን ሲቀበለን በምድረ በ5 የሚዘዋወረው ይህ ሰበው ማነው ጣላ ያንን ብላቲና ጠየቱችው ፡ አሱም ጌታዬ ይህ ነው አላት ፡ አሷም መጐናጸፍያዋን አንመሥታ ፊቷን ተክ R 4c IR ER ) Hy, Ny ES ክርስቲያን ሃይማናኛችትናኛ ሥርዓ ፅራፍ ፳ጀ።",
