    (30, 13, "እሁንም ከወንድሜ ከዔሳው አጅ አድነኝ መጥቶ እን ዳይገድለኝ ከሱ የተነሣ ለራሌ እፈራለሁና ፡ አናትን ከል ጆቹ ጋር እንዳይገድል አለ።"),
    (30, 14, "በጎ ነገርን ኣዶርግሃለሁ ብለሽኛልና ፡ ከብዛቱም የተ ነሣ የልጅ ልጅህን እንደማይቴጠር አሸዋ እዶርገዋለሁ ብለሽኝ ነበርና።"),
